def merge_live_sensor_issues(issues, live):
    """Use the integrated Pi cache for SMS incidents, without changing actuation."""
    sensors = live.get("sensors") if isinstance(live, dict) else None
    if not isinstance(sensors, dict):
        return issues
    for name in ("ph", "ec", "water_temperature", "turbidity", "ambient_humidity"):
        sensor = sensors.get(name)
        if not isinstance(sensor, dict):
            continue
        key = f"sensor:{name}:status"
        # Legacy adapters are intentionally disabled on Pi to avoid a second
        # hardware owner. Their pending status must not become a GSM event.
        issues.pop(key, None)
        status = str(sensor.get("status") or "")
        failures = sensor.get("consecutive_failures", 0)
        persistent = (isinstance(failures, int) and not isinstance(failures, bool)
                      and failures >= 2)
        if status.startswith("ERROR") or (sensor.get("valid") is False and persistent):
            issues[key] = {
                "source": "sensor", "severity": "critical",
                "message": f"{SENSOR_LABELS[name]} fault: {status}",
            }
    return issues

def record_issue_transitions(self, current_issues):
    opened = set(current_issues) - set(self.active_issues)
    resolved = set(self.active_issues) - set(current_issues)
    transition_time = now()
    for key in sorted(opened):
        issue = current_issues[key]
        issue["opened_at"] = transition_time
        self.event("problem_opened", issue["message"], {
            "issue_key": key, "source": issue["source"],
            "severity": issue["severity"], "state": "OPEN",
            "opened_at": transition_time,
        })
    for key in sorted(resolved):
        issue = self.active_issues[key]
        self.event("problem_resolved", f"Resolved: {issue['message']}", {
            "issue_key": key, "source": issue["source"],
            "severity": "resolved", "state": "RESOLVED",
            "opened_at": issue.get("opened_at"),
            "acknowledged_at": self.acknowledged_issues.get(key),
            "resolved_at": transition_time,
        })
        self.acknowledged_issues.pop(key, None)
    for key in set(current_issues) & set(self.active_issues):
        current_issues[key]["opened_at"] = self.active_issues[key].get("opened_at")
    self.active_issues = copy.deepcopy(current_issues)
    return opened, resolved

def acknowledge_issue(self, issue_key):
    if not isinstance(issue_key, str) or not issue_key or len(issue_key) > 200:
        raise ValueError("A valid issue_key is required")
    with self.lock:
        issue = self.active_issues.get(issue_key)
        if issue is None:
            raise LookupError("The incident is no longer active")
        if issue_key in self.acknowledged_issues:
            return self.incident(issue_key, issue)
        acknowledged_at = now()
        self.acknowledged_issues[issue_key] = acknowledged_at
        self.event("problem_acknowledged", f"Acknowledged: {issue['message']}", {
            "issue_key": issue_key, "source": issue["source"],
