            "opened_at": issue.get("opened_at"),
            "acknowledged_at": acknowledged_at,
        })
        acknowledged = self.incident(issue_key, issue)
        if self.state:
            self.state["incidents"] = [
                self.incident(key, active_issue)
                for key, active_issue in sorted(self.active_issues.items())
            ]
