        issue = self.active_issues[key]
        notice = issue["severity"] == "notice"
        self.event("notification_ended" if notice else "problem_resolved",
                   f"Ended: {issue['message']}" if notice else f"Resolved: {issue['message']}", {
            "issue_key": key, "source": issue["source"],
            "severity": "notice" if notice else "resolved",
