            "opened_at": issue.get("opened_at"),
            "acknowledged_at": self.acknowledged_issues.get(key),
            "resolved_at": transition_time,
        })
        self.acknowledged_issues.pop(key, None)
        self.notification_delivered.discard(key)
        self.notification_retry_after.pop(key, None)
    for key in set(current_issues) & set(self.active_issues):
        current_issues[key]["opened_at"] = self.active_issues[key].get("opened_at")
    self.active_issues = copy.deepcopy(current_issues)
    return opened, resolved

def acknowledge_issue(self, issue_key):
    if not isinstance(issue_key, str) or not issue_key or len(issue_key) > 200:
        raise ValueError("A valid issue_key is required")
    with self.lock:
        issue = self.active_issues.get(issue_key)
        if issue is None:
            raise LookupError("The incident is no longer active")
        if issue["severity"] == "notice":
            raise ValueError("Notifications do not require acknowledgement")
        if issue_key in self.acknowledged_issues:
            return self.incident(issue_key, issue)
        acknowledged_at = now()
        self.acknowledged_issues[issue_key] = acknowledged_at
        self.event("problem_acknowledged", f"Acknowledged: {issue['message']}", {
            "issue_key": issue_key, "source": issue["source"],
            "severity": issue["severity"], "state": "ACKNOWLEDGED",
            "opened_at": issue.get("opened_at"),
            "acknowledged_at": acknowledged_at,
        })
        acknowledged = self.incident(issue_key, issue)
        if self.state:
            self.state["incidents"] = [
                self.incident(key, active_issue)
                for key, active_issue in sorted(self.active_issues.items())
            ]
        return acknowledged

def incident(self, issue_key, issue):
    acknowledged_at = self.acknowledged_issues.get(issue_key)
    return {
        "issue_key": issue_key,
        "source": issue["source"],
        "severity": issue["severity"],
        "message": issue["message"],
        "state": "NOTICE" if issue["severity"] == "notice" else
                 "ACKNOWLEDGED" if acknowledged_at else "OPEN",
        "opened_at": issue.get("opened_at"),
        "acknowledged_at": acknowledged_at,
    }

issues = enrich_issues(issues, live_snapshot, locals().get("fusion_by_slot"))
self.record_issue_transitions(issues)
for issue_key in sorted(issues):
    issue = issues[issue_key]
    if issue_key in self.notification_delivered:
        continue
    if time.monotonic() < self.notification_retry_after.get(issue_key, 0):
        continue
    if not self.gsm.should_notify(issue_key, issue):
        continue
    result = guarded(lambda issue_key=issue_key, issue=issue: self.gsm.send(
        format_sms_alert(issue_key, issue)))
    self.event("notification", result.status, {
        "issue_key": issue_key, "result": result.as_dict(),
    })
    if result.status in ("SENT", "NOT SENT — COOLDOWN"):
        self.notification_delivered.add(issue_key)
        self.notification_retry_after.pop(issue_key, None)
    else:
        self.notification_retry_after[issue_key] = time.monotonic() + 60
